onical":"NewWinPay","aliases":["newwinpay2inr-paytmqr","newwinpay"]},{"id":"m8-rapay","match":{"sourceKind":"native_prepared","team":"M8","scope":"IN","currency":"INR"},"canonical":"RAPay","aliases":["rapayinr-bank","rapayinr-qr","rapay"]},{"id":"m8-wpay","match":{"sourceKind":"native_prepared","team":"M8","scope":"IN","currency":"INR"},"canonical":"WPay","aliases":["wpayinr","wpay"]},{"id":"confirmed-tigerpa-red-crab-india","match":{"sourceKind":"team_sheet","source":"red_crab_india","team":"红膏蟹","country":"印度","scope":"IN","currency":"INR"},"canonical":"TigerPay","aliases":["tigerpa","tigerpay"]},{"id":"confirmed-moneypay-qr-oct29","match":{"country":"印度","currency":"INR"},"canonical":"MoneyPay","aliases":["moneypay-qr","moneypay"]}],"version":"d4caf1bfe525fdcb00a06da09e9a71b4c8bee3336fcc63d74b5b745de1aa2338"}$alias_payload$)
 ) v(signature,marker,baseline_hash,desired_hash,replacement) loop
  select * into p from pg_proc where oid=to_regprocedure(item.signature);
  if not found or p.proowner<>'postgres'::regrole or p.proacl::text is distinct from '{postgres=X/postgres}' or p.prosecdef or p.provolatile<>'i' or p.proconfig is distinct from array['search_path=""']::text[] then raise exception 'india_provider_alias_metadata_or_acl_drift: %',item.signature;end if;
  if md5(p.prosrc)=item.desired_hash then continue;end if;
  if md5(p.prosrc)<>item.baseline_hash then raise exception 'india_provider_alias_baseline_drift: %',item.signature;end if;
  metadata:=to_jsonb(p)-'prosrc';definition:=pg_get_functiondef(p.oid);
  if (length(definition)-length(replace(definition,item.marker,'')))/length(item.marker)<>2 then raise exception 'india_provider_alias_marker_drift: %',item.signature;end if;
  original:=split_part(definition,item.marker,2);perform original::jsonb;perform item.replacement::jsonb;
  execute replace(definition,item.marker||original||item.marker,item.marker||item.replacement||item.marker);
  select * into p from pg_proc where oid=to_regprocedure(item.signature);
  if (to_jsonb(p)-'prosrc') is distinct from metadata or md5(p.prosrc)<>item.desired_hash then raise exception 'india_provider_alias_installation_drift: %',item.signature;end if;
 end loop;
end;
$patch$;
notify pgrst,'reload schema';
commit;
